  ('cebuano-a2-practical-5', 'cebuano-a2-practical-5-044-dili-kini-kana', 'bright', 'Bisaya', 'Pasaylo, dili kini; kana ang akong gusto.', '122d049be4ed804d95cef6d9c05bddc18a8de0f07bdb27fc078c47f7f31d5e40'),
  ('cebuano-a2-practical-5', 'cebuano-a2-practical-5-044-dili-kini-kana', 'bright', 'English', 'Sorry, not these; those are the ones I want.', '122d049be4ed804d95cef6d9c05bddc18a8de0f07bdb27fc078c47f7f31d5e40'),
